SELECT SUM(returns.amount) AS total_damaged_returns_cost
FROM `pplk8s-lab-001`.`silver`.`returns` AS RETURNS
WHERE LOWER(returns.reason) = 'damaged';

SELECT COUNT(DISTINCT customer_id) AS total_customers
FROM `pplk8s-lab-001.silver.customers`
WHERE signup_date <= DATE '2026-09-30';

SELECT COUNT(*) AS total_leads
FROM `pplk8s-lab-001.silver.leads` AS leads
WHERE leads.created_date BETWEEN DATE '2026-09-01' AND DATE '2026-09-10';

SELECT COUNT(*) AS total_orders
FROM `pplk8s-lab-001.silver.orders` AS orders
WHERE orders.order_date = DATE '2026-10-01';

SELECT COUNT(DISTINCT customer_id) AS distinct_customers
FROM `pplk8s-lab-001.silver.orders`
WHERE order_date = '2026-10-02';

SELECT COUNT(DISTINCT customer_id) AS total_customers_signed_up
FROM `pplk8s-lab-001.silver.customers`
WHERE signup_date <= DATE '2026-09-30';

SELECT DISTINCT PERCENTILE_CONT(amount, 0.5) OVER() AS median_order_value
FROM `pplk8s-lab-001.silver.orders`
WHERE order_date = DATE '2026-10-01';

SELECT COUNT(leads.lead_id) AS lead_count
FROM `pplk8s-lab-001.silver.leads` AS leads
WHERE leads.created_date BETWEEN DATE '2026-09-01' AND DATE '2026-09-10';
